corporate_design.toad_component_blueprint:
canvas {
  size: 880px 560px;
  fill: #F8FAFC;
  font-family: "Barlow, sans-serif";
}

>petrol = #0E7490;
>coral = #F43F5E;

rect #climbCard {
  at: center of canvas;
  size: 780px 460px;
  fill: #FFFFFF;
  stroke: >petrol;
  stroke-width: 2px;
  radius: 16px;
}

text #climbHeader {
  at: top left of #climbCard offset 36px 36px;
  content: "SUMMIT BOULDER // NEUE SCHRAUBUNG JEDEN MONTAG";
  font-size: 13px;
  font-weight: 800;
  color: >coral;
}

text #climbTitle {
  at: below #climbHeader offset 14px;
  content: "2.500 m² pure Kletterfreude & Kaffeegenuss";
  font-size: 30px;
  font-weight: 800;
  color: >petrol;
}
